// Lead Status classification helpers for consistency
const isWonStatus = (status) => {
  const s = (status || "").trim().toLowerCase();
  return s === "won" || s === "closed won" || s === "renewal won" || s === "renewed";
};

const isLostStatus = (status) => {
  const s = (status || "").trim().toLowerCase();
  return s === "lost" || s === "junk" || s === "closed lost" || s === "deal lost" || s === "dropped" || s === "disqualified" || s.includes("lost");
};

const isActiveStatus = (status) => {
  const s = (status || "").trim().toLowerCase();
  return s !== "" && !isWonStatus(status) && !isLostStatus(status);
};

const isTaskLinkedToLostLead = (task, leadsList) => {
  if (!task || !leadsList || leadsList.length === 0) return false;
  const linked = (task.linkedLeadId && leadsList.find(l => l.id === task.linkedLeadId)) ||
                 (task.title && leadsList.find(l => l.name && l.name.length > 2 && task.title.toLowerCase().includes(l.name.toLowerCase())));
  return linked ? isLostStatus(linked.status) : false;
};

const isRenewalLead = (lead) => {
  if (!lead) return false;
  const s = (lead.status || "").trim().toLowerCase();
  const dt = (lead.deal_type || "").trim().toLowerCase();
  const ps = (lead.previous_stage || "").trim().toLowerCase();
  const src = (lead.source || "").trim().toLowerCase();
  const notes = typeof lead.notes === "string" ? lead.notes.toLowerCase() : Array.isArray(lead.notes) ? lead.notes.map(n => n.text || "").join(" ").toLowerCase() : "";
  const name = (lead.name || "").toLowerCase();
  const company = (lead.company || "").toLowerCase();
  
  return s === "renewal" || s === "renewed" || s === "renewal won" || s.includes("renewal") ||
         dt === "renewal" || ps === "renewal" || src === "renewal" || src.includes("renewal") ||
         notes.includes("renewal") || name.includes("renewal") || company.includes("renewal");
};

const isRenewalWonLead = (lead) => {
  if (!lead) return false;
  return isWonStatus(lead.status) && isRenewalLead(lead);
};

// Avatar & Stage Badge helpers for HubSpot/LeadSquared Style UI
const getAvatarInitials = (name) => {
  if (!name || typeof name !== "string") return "L";
  const clean = name.trim();
  const parts = clean.split(/\s+/);
  if (parts.length === 1) return clean.slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
};

const AVATAR_PALETTES = [
  { bg: "#eff6ff", text: "#1d4ed8", border: "#bfdbfe" }, // blue
  { bg: "#f5f3ff", text: "#6d28d9", border: "#ddd6fe" }, // purple
  { bg: "#ecfdf5", text: "#047857", border: "#a7f3d0" }, // emerald
  { bg: "#fff7ed", text: "#c2410c", border: "#fed7aa" }, // orange
  { bg: "#fdf2f8", text: "#be185d", border: "#fbcfe8" }, // pink
  { bg: "#f0fdfa", text: "#0f766e", border: "#99f6e4" }, // teal
];

const getAvatarColor = (name) => {
  if (!name) return AVATAR_PALETTES[0];
  let hash = 0;
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash);
  }
  const idx = Math.abs(hash) % AVATAR_PALETTES.length;
  return AVATAR_PALETTES[idx];
};

