// Helper to build full permissions object with fallback defaults
export function buildDefaultPermissions(overrides = {}) {
  const base = {};
  ALL_PERMISSION_CATEGORIES.forEach(cat => {
    cat.items.forEach(item => {
      base[item.key] = false;
    });
  });
  return { ...base, ...overrides };
}

