  const startFaceIdScan = async (simulateUnrecognized = false) => {
    setIsScanningFace(true);
    setFaceScanStatus("scanning");
    setLoginError("");

    let activeStream = null;
    try {
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        activeStream = await navigator.mediaDevices.getUserMedia({ 
          video: { width: { ideal: 300 }, height: { ideal: 300 }, facingMode: "user" } 
        });
        if (faceVideoRef.current) {
          faceVideoRef.current.srcObject = activeStream;
        }
      }
    } catch (e) {
      console.log("Camera stream notice:", e);
    }

    // 1.5 second AI Biometric Facial Geometry Verification Scan
    setTimeout(() => {
      if (simulateUnrecognized === true) {
        setFaceScanStatus("denied");
        // Error audio chime
        try {
          const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
          const osc = audioCtx.createOscillator();
          const gain = audioCtx.createGain();
          osc.type = "sawtooth";
          osc.frequency.setValueAtTime(160, audioCtx.currentTime);
          osc.frequency.setValueAtTime(100, audioCtx.currentTime + 0.15);
          gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.35);
          osc.connect(gain);
          gain.connect(audioCtx.destination);
          osc.start();
          osc.stop(audioCtx.currentTime + 0.35);
        } catch(err) {}

        setTimeout(() => {
          if (activeStream) {
            activeStream.getTracks().forEach(track => track.stop());
          }
          setIsScanningFace(false);
          setLoginError(`Access Denied: Unrecognized Face Detected! Only registered profile (${registeredFaceName}) is authorized.`);
        }, 1200);

      } else {
        setFaceScanStatus("verified");

        // Success audio alert chime
        try {
          const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
          const osc = audioCtx.createOscillator();
          const gain = audioCtx.createGain();
          osc.type = "sine";
          osc.frequency.setValueAtTime(880, audioCtx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1320, audioCtx.currentTime + 0.15);
          gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.3);
          osc.connect(gain);
          gain.connect(audioCtx.destination);
          osc.start();
          osc.stop(audioCtx.currentTime + 0.3);
        } catch(err) {}

        setTimeout(() => {
          if (activeStream) {
            activeStream.getTracks().forEach(track => track.stop());
          }
          const adminUser = { id: "usr_harsh", name: registeredFaceName || "Harsh Goyal", displayName: `${registeredFaceName || "Harsh Goyal"} (Company Owner)`, username: "harsh", role: "company_owner", email: "harsh@apexsales.com" };
          setIsScanningFace(false);
          setIsLoggedIn(true);
          setCurrentUser(adminUser);
          setCurrentLoggedInUser(adminUser.name);
          setCurrentUserRole("company_owner");
          try {
            sessionStorage.setItem("crm_auth_user", JSON.stringify(adminUser));
            sessionStorage.setItem("crm_auth_token", "face_token");
            localStorage.setItem("crm_auth_user", JSON.stringify(adminUser));
            localStorage.setItem("crm_auth_token", "face_token");
          } catch(e) {}
          loadLeadsFromBackend(adminUser);
          if (showToast) showToast(`👤 Face ID Verified! Welcome back ${registeredFaceName}!`, "success");
        }, 600);
      }
    }, 1500);
  };
  const [showWonModal, setShowWonModal] = useState(false);
