  // Follow-up Helper
  const sendWhatsAppFollowUp = async (lead, customMsg, sendToSelf = false) => {
    if (!lead) return;
    if (showToast) showToast(`Scheduled follow-up for ${lead.name}`);
  };

  // Real-time WhatsApp Follow-up Alarm Checker Engine (Runs every 10 seconds)
  useEffect(() => {
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission();
    }

    const interval = setInterval(() => {
      const now = new Date();
      const todayStr = now.toISOString().slice(0, 10);
      const currentHHMM = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

      leads.forEach(l => {
        if (isActiveStatus(l.status) && l.next_follow_up === todayStr) {
          const scheduledTime = l.follow_up_time || "10:00";
          if (scheduledTime === currentHHMM && !l.alarmTriggeredToday) {
            l.alarmTriggeredToday = true;
            setWaAlarmLead(l);

            // Automatically dispatch real WhatsApp message to phone if API Key is configured!
            if (whatsappApiKey && whatsappApiKey.trim() !== "") {
              sendWhatsAppFollowUp(l, null, true);
            }

            // Audio Alert Chime
            try {
              const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
              const osc = audioCtx.createOscillator();
              const gain = audioCtx.createGain();
              osc.connect(gain);
              gain.connect(audioCtx.destination);
              osc.frequency.value = 880;
              gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
              osc.start();
              osc.stop(audioCtx.currentTime + 0.35);
            } catch(e) {}

            // Desktop Push Notification
            if ("Notification" in window && Notification.permission === "granted") {
              new Notification(`⏰ Follow-Up Alarm: ${l.name}`, {
                body: `Company: ${l.company || "N/A"} | Scheduled Time: ${scheduledTime}`
              });
            }
          }
        }
      });
    }, 10000);

    return () => clearInterval(interval);
  }, [leads, autoOpenWaWeb, whatsappApiKey]);

