                        const csvRows = filteredReportLeads.map(l => `"${l.name || ""}","${l.company || ""}","${l.phone || ""}","${l.email || ""}",${l.value || 0},"${l.status || ""}","${l.source || ""}","${l.score || ""}","${l.won_date || ""}","${l.next_follow_up || ""}"`).join("\n");
                        const blob = new Blob([csvHeader + csvRows], { type: "text/csv" });
                        const url = URL.createObjectURL(blob);
                        const a = document.createElement("a");
