                                color: unassignedAgingCriticalCount > 0 ? "#dc2626" : "#ea580c",
                                border: `1px solid ${unassignedAgingCriticalCount > 0 ? "#fecaca" : "#fed7aa"}`,
                                borderRadius: "6px",
                                fontSize: "12px",
                                fontWeight: "600",
                                cursor: "pointer",
                                transition: "all 0.15s ease"
