                            const stageBg = stageLower.includes("payment") ? "#ffedd5" : stageLower.includes("renewal") ? "#ccfbf1" : "#e0e7ff";
                            const stageTextColor = stageLower.includes("payment") ? "#c2410c" : stageLower.includes("renewal") ? "#0f766e" : "#3730a3";

