                                      fontSize: "12px",
                                      fontWeight: "600",
                                      cursor: "pointer",
                                      whiteSpace: "nowrap",
                                      boxShadow: isUrgent ? "0 1px 2px rgba(37, 99, 235, 0.2)" : "0 1px 2px rgba(0,0,0,0.02)",
