                                      color: "#ffffff",
                                      border: "none",
                                      borderRadius: "6px",
                                      padding: "6px 14px",
                                      fontSize: "12px",
                                      fontWeight: "600",
                                      fontFamily: "'Plus Jakarta Sans', sans-serif",
                                      cursor: "pointer",
                                      whiteSpace: "nowrap",
                                      boxShadow: "0 1px 2px rgba(234, 88, 12, 0.2)"
