                        const wonSrcLeads = srcLeads.filter(l => isWonStatus(l.status));
                        const wonRev = wonSrcLeads.reduce((sum, l) => sum + (Number(l.value) || 0), 0);
                        const convRate = srcLeads.length > 0 ? ((wonSrcLeads.length / srcLeads.length) * 100).toFixed(1) : 0;

